mapper.select:
SELECT godd.ID_ORDEN_DESPACHO_DETALLE, godd.CANTIDAD, godd.POSICION, godd.NUMERO_ORDEN_COMPRA, godd.CODIGO_SAP_ALMACEN, godd.DENOMINACION_ALMACEN, godd.CODIGO_SAP_BIEN_SERVICIO, godd.DESCRIPCION_BIEN_SERVICIO, godd.CODIGO_SAP_CENTRO, godd.DENOMINACION_CENTRO, godd.DIRECCION_CENTRO, godd.FECHA_ENTREGA, godd.ID_ORDEN_DESPACHO, godd.INDICADOR_IMPUESTO, godd.PRECIO_TOTAL, godd.PRECIO_UNITARIO, godd.TIPO_POSICION, godd.UNIDAD_MEDIDA_BIEN_SERVICIO, COALESCE( SUM( CASE WHEN ggd.ID_ESTADO_DESPACHO IN (1,5) THEN ggdd.CANTIDAD_ESTE_DESPACHO ELSE 0 END ), 0 ) AS TOTAL_DESPACHADO, godd.CANTIDAD - COALESCE( SUM( CASE WHEN ggd.ID_ESTADO_DESPACHO IN (1,5) THEN ggdd.CANTIDAD_ESTE_DESPACHO ELSE 0 END ), 0 ) AS CANTIDAD_RESTANTE FROM GA_ORDEN_DESPACHO_DETALLE godd INNER JOIN GA_ORDEN_DESPACHO god ON god.NUMERO_ORDEN_COMPRA = godd.NUMERO_ORDEN_COMPRA LEFT JOIN GA_GUIA_DESPACHO_DETALLE ggdd ON ggdd.POSICION = godd.POSICION AND ggdd.NUMERO_ORDEN_DESPACHO = godd.NUMERO_ORDEN_COMPRA LEFT JOIN GA_GUIA_DESPACHO ggd ON ggd.ID_GUIA_DESPACHO = ggdd.ID_GUIA_DESPACHO WHERE god.IS_ACTIVE = '1'
AND godd.NUMERO_ORDEN_COMPRA = #{numeroOrdenCompra}
AND god.PROVEEDOR_RUC = #{ruc}
GROUP BY godd.ID_ORDEN_DESPACHO_DETALLE, godd.CANTIDAD, godd.POSICION, godd.NUMERO_ORDEN_COMPRA, godd.CODIGO_SAP_ALMACEN, godd.DENOMINACION_ALMACEN, godd.CODIGO_SAP_BIEN_SERVICIO, godd.DESCRIPCION_BIEN_SERVICIO, godd.CODIGO_SAP_CENTRO, godd.DENOMINACION_CENTRO, godd.DIRECCION_CENTRO, godd.FECHA_ENTREGA, godd.ID_ORDEN_DESPACHO, godd.INDICADOR_IMPUESTO, godd.PRECIO_TOTAL, godd.PRECIO_UNITARIO, godd.TIPO_POSICION, godd.UNIDAD_MEDIDA_BIEN_SERVICIO ORDER BY godd.POSICION ASC
